# ============================================================================
# Figure 4: Event Study - Effect on Dismissed Workers
# ============================================================================

library(dplyr)
library(tidyr)
library(ggplot2)
library(cowplot)
library(haven)

rm(list = ls())

# ============================================================================
# Load event study results for workers
# ============================================================================

# Load the .dta files generated by parmby in Stata for worker-level analysis
# These should contain results for outcomes related to dismissed workers

empregados_95 <- haven::read_dta("empregados_95.dta") %>%
  filter(grepl("treat_", parm)) %>%
  mutate(
    outcome = "Dismissed Workers",
    parmseq = parmseq - 5
  ) %>%
  rename(min = min95, max = max95)

# ============================================================================
# Create event study plot
# ============================================================================

plot <- ggplot(empregados_95, aes(x = parmseq, y = estimate)) +
  geom_point(size = 3, color = "darkblue") +
  geom_line(linetype = "solid", color = "darkblue") +
  geom_ribbon(aes(ymin = min, ymax = max), alpha = 0.2, fill = "lightblue") +
  geom_hline(yintercept = 0, linetype = "dashed", color = "black", alpha = 0.5) +
  geom_vline(xintercept = 0.5, linetype = "dashed", color = "red", alpha = 0.5) +
  theme_bw() +
  theme(
    plot.title = element_text(size = 12, face = "bold"),
    axis.text.x = element_text(angle = 45, hjust = 1)
  ) +
  labs(
    title = "Event Study: Effect of Disaster-induced Closures on Dismissed Workers",
    x = "Years Relative to Disaster (2008)",
    y = "Coefficient (95% CI)"
  )

# ============================================================================
# Save plot
# ============================================================================

ggsave(
  "Fig_04_Event_Study_Dismissed_Workers.png",
  plot,
  dpi = 300,
  width = 12,
  height = 6,
  units = "in"
)

cat("Figure 4 saved: Fig_04_Event_Study_Dismissed_Workers.png\n")
